<?php
$now42 = new DateTimeImmutable('today',new DateTimeZone(sf_config()['timezone']));
$days42 = array_column($sf42Days ?? [], null, 'workout_date');
$monthRows42 = array_column($sf42Monthly ?? [], null, 'month_key');
$month42 = $now42->modify('first day of this month');
$fmt42 = static fn($v,$d=0)=>number_format((float)$v,$d,',','.');
$series42=[];
for($i=83;$i>=0;$i--){$date=$now42->modify('-'.$i.' days');$key=$date->format('Y-m-d');$row=$days42[$key]??[];$series42[]=['date'=>$key,'label'=>$date->format('d/m'),'seconds'=>max(0,(int)($row['seconds']??0)),'sessions'=>max(0,(int)($row['sessions']??0))];}
?>
<section class="sf42-panel sf42-performance" data-arena-panel="insights" data-sf42-performance aria-label="Báo cáo luyện tập">
<header class="sf42-head"><div><span class="sf42-eyebrow">HIỆU SUẤT CÁ NHÂN</span><h2>Hành trình luyện tập</h2></div><div class="sf42-switch" role="group" aria-label="Khoảng thời gian"><?php foreach([7=>'7 ngày',30=>'30 ngày',84=>'12 tuần'] as $n=>$label):?><button type="button" data-sf42-period="<?= $n ?>" aria-pressed="<?= $n===84?'true':'false' ?>"><?= $label ?></button><?php endforeach;?></div></header>
<script type="application/json" data-sf42-series><?= json_encode($series42,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?></script>
<div class="sf42-kpis"><div><span>Buổi hợp lệ</span><strong data-sf42-stat="sessions"><?= array_sum(array_column($series42,'sessions')) ?></strong></div><div><span>Tổng giờ tập</span><strong data-sf42-stat="hours"><?= $fmt42(array_sum(array_column($series42,'seconds'))/3600,1) ?></strong></div><div><span>Ngày đã tập</span><strong data-sf42-stat="days"><?= count(array_filter($series42,static fn($d)=>$d['sessions']>0)) ?></strong></div><div><span>Phút / buổi</span><strong data-sf42-stat="average"><?= array_sum(array_column($series42,'sessions')) ? $fmt42(array_sum(array_column($series42,'seconds'))/60/array_sum(array_column($series42,'sessions')),1):'—' ?></strong></div></div>
<div class="sf42-chart-area"><div class="sf42-chart-head"><h3>Thời gian tập mỗi ngày</h3><span>Phút</span></div><svg data-sf42-plot viewBox="0 0 640 190" role="img" aria-label="Biểu đồ thời gian luyện tập"><text x="320" y="95" text-anchor="middle" fill="currentColor">Đang chuẩn bị biểu đồ…</text></svg><p data-sf42-point class="sf42-detail" aria-live="polite">Chọn một điểm để xem chi tiết.</p></div>
<div class="sf42-heat-head"><div><h3>Lịch hoạt động</h3><p>84 ngày gần nhất · chọn từng ngày để xem thời lượng.</p></div><div class="sf42-legend"><span>Ít</span><i></i><i></i><i></i><i></i><span>Nhiều</span></div></div>
<div class="sf42-heat-scroll"><div class="sf42-heat-labels" aria-hidden="true"><?php foreach(['T2','T3','T4','T5','T6','T7','CN'] as $l):?><span><?= $l ?></span><?php endforeach;?></div><div class="sf42-heat-grid" style="--sf42-cols:<?= (int)ceil(((int)(new DateTimeImmutable($series42[0]['date']))->format('N')-1+84)/7) ?>"><?php for($i=1;$i<(int)(new DateTimeImmutable($series42[0]['date']))->format('N');$i++):?><span aria-hidden="true"></span><?php endfor;foreach($series42 as $i=>$d):$level=$d['sessions']===0?0:($d['seconds']<1800?1:($d['seconds']<3600?2:3));?><button type="button" data-sf42-day="<?= $i ?>" data-level="<?= $level ?>" title="<?= sf_h($d['label'].' · '.$fmt42($d['seconds']/60,1).' phút') ?>" aria-label="<?= sf_h($d['label'].' · '.$d['sessions'].' buổi · '.$fmt42($d['seconds']/60,1).' phút') ?>"></button><?php endforeach;?></div></div>
<p class="sf42-detail" data-sf42-heat-detail aria-live="polite">Chưa chọn ngày.</p>
<noscript><p>Biểu đồ tương tác cần JavaScript; tổng số và lịch hoạt động vẫn hiển thị.</p></noscript>
</section>
<section class="sf42-panel sf42-month" data-arena-panel="insights"><header class="sf42-head"><div><span class="sf42-eyebrow">BÁO CÁO THÁNG</span><h2>So sánh luyện tập</h2></div></header><div class="sf42-month-grid"><?php foreach([[$month42,'Tháng này (đến hôm nay)'],[$month42->modify('-1 month'),'Tháng trước (trọn tháng)']] as [$m,$label]):$d=$monthRows42[$m->format('Y-m')]??[];?><article><span><?= sf_h($label) ?> · <?= $m->format('m/Y') ?></span><strong><?= (int)($d['sessions']??0) ?> <small>buổi</small></strong><div><span><?= $fmt42(((int)($d['seconds']??0))/3600,1) ?> giờ</span><span><?= (int)($d['days']??0) ?> ngày tập</span></div></article><?php endforeach;?></div><p class="sf42-note">Tháng hiện tại chưa kết thúc. Chỉ tính buổi hợp lệ, không tính thời gian đang tập.</p></section>
